import {validPolygon} from './geo.mjs';
export const sourceSize=v=>{const m=String(v??'').trim().match(/^(\d+(?:\.\d+)?)\s*(?:m)?$/);return m&&+m[1]>0&&+m[1]<100?+m[1]:null;};
export function clipSegment(a,b,s){let lo=0,hi=1;const d=[b[0]-a[0],b[1]-a[1]];for(let i=0;i<2;i++){if(!d[i]){if(a[i]<0||a[i]>s)return null;continue;}let u=-a[i]/d[i],v=(s-a[i])/d[i];if(u>v)[u,v]=[v,u];lo=Math.max(lo,u);hi=Math.min(hi,v);if(lo>hi)return null;}return [a.map((v,i)=>v+d[i]*lo),a.map((v,i)=>v+d[i]*hi)];}
export function sampledSegment(a,b,step=5){const n=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/step));return Array.from({length:n+1},(_,i)=>a.map((v,j)=>v+(b[j]-v)*i/n));}
export function addLandscape(T,scene,features,{xy,elevation,side,layers={paths:true,trees:true,objects:true,surfaces:true}}){
const counts={paths:0,trees:0,objects:0,surfaces:0,symbolic:0,skipped:0};const materials=new Map();const mat=(color)=>{if(!materials.has(color))materials.set(color,new T.MeshStandardMaterial({color,side:T.DoubleSide}));return materials.get(color);};
const pos=([x,y],h=.18)=>[x-side/2,elevation(x,y)+h,side/2-y];
function lines(coords,color){let added=false;for(let i=1;i<coords.length;i++){const c=clipSegment(xy(coords[i-1]),xy(coords[i]),side);if(!c)continue;added=true;const points=sampledSegment(...c).map(p=>new T.Vector3(...pos(p,.25)));scene.add(new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color})));}return added;}
function marker(p,kind,tags={}){const q=xy(p);if(q.some(v=>v<0||v>side))return false;const origin=pos(q,0);const mesh=(g,color,y)=>{const m=new T.Mesh(g,mat(color));m.position.set(origin[0],origin[1]+y,origin[2]);scene.add(m);};if(kind==='tree'){const h=sourceSize(tags.height)||3.4,d=sourceSize(tags.diameter_crown)||2.4,r=Math.min(d/2,h*.7);mesh(new T.CylinderGeometry(.13,.18,h*.5,6),0x70543a,h*.25);const crown=new T.SphereGeometry(1,8,6);crown.scale(d/2,r,d/2);mesh(crown,0x46764c,h-r);}else if(kind==='street_lamp'){mesh(new T.CylinderGeometry(.08,.1,3,6),0x687e87,1.5);mesh(new T.SphereGeometry(.25,6,4),0xf3e5b5,3);}else if(kind==='waste_basket'){mesh(new T.CylinderGeometry(.25,.22,.7,8),0x687e87,.35);}else if(kind==='bicycle_parking'){mesh(new T.TorusGeometry(.5,.06,4,8,Math.PI),0x687e87,.1);}else if(kind==='bench'){mesh(new T.BoxGeometry(1.8,.25,.6),0x815f43,.5);}else if(kind==='fountain'){mesh(new T.CylinderGeometry(1,1,.25,12),0x66adc3,.18);}else{mesh(new T.BoxGeometry(.6,.8,.6),0x687e87,.4);}return true;}
for(const f of features){const p=f.properties||{},g=f.geometry;if(!g||p.tainted)continue;if(['construction','proposed'].includes(p.highway)){counts.skipped++;continue;}if((p.bridge&&p.bridge!=='no')||(p.tunnel&&p.tunnel!=='no')){counts.skipped++;continue;}if(layers.paths&&p.highway&&['LineString','MultiLineString'].includes(g.type)){let added=false;for(const l of g.type==='LineString'?[g.coordinates]:g.coordinates)added=lines(l,['footway','path','pedestrian','steps','cycleway'].includes(p.highway)?0xb19d79:0x8d8b83)||added;if(added){counts.paths++;counts.symbolic++;}}
if((layers.objects&&p.barrier||layers.trees&&p.natural==='tree_row')&&g.type==='LineString'){if(lines(g.coordinates,0x55764c)){counts.objects++;counts.symbolic++;}}if(g.type==='Point'){if(layers.trees&&p.natural==='tree'){if(marker(g.coordinates,'tree',p)){counts.trees++;counts.symbolic++;}}else if(layers.objects&&(['bench','waste_basket','fountain','bicycle_parking','drinking_water'].includes(p.amenity)||p.highway==='street_lamp')){if(marker(g.coordinates,p.amenity||p.highway,p)){counts.objects++;counts.symbolic++;}}}
if(layers.surfaces&&['river','stream','canal','drain','ditch'].includes(p.waterway)&&g.type==='LineString'){if(lines(g.coordinates,0x72a9bd)){counts.surfaces++;counts.symbolic++;}}const road=!!p['area:highway']||(p.highway&&p.area==='yes')||p.amenity==='parking';const green=['wood','grassland','scrub'].includes(p.natural)||['forest','grass','meadow','recreation_ground'].includes(p.landuse)||['park','garden'].includes(p.leisure),water=p.natural==='water'||p.water||['reservoir','basin'].includes(p.landuse),play=['playground','pitch'].includes(p.leisure);if(!layers.surfaces||!(green||water||play||road))continue;
for(const poly of g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[]){if(!validPolygon(poly)){counts.skipped++;continue;}const rings=poly.map(r=>r.map(xy));if(rings.some(r=>r.some(q=>q.some(v=>v<0||v>side)))){for(const r of poly)lines(r,water?0x72a9bd:0x729666);continue;}const contour=rings[0].slice(0,-1).map(q=>new T.Vector2(...q)),holes=rings.slice(1).map(r=>r.slice(0,-1).map(q=>new T.Vector2(...q))),all=[...contour,...holes.flat()];const faces=T.ShapeUtils.triangulateShape(contour,holes),verts=[];function tri(a,b,c,depth=0){if(depth<8&&Math.max(a.distanceTo(b),b.distanceTo(c),c.distanceTo(a))>Math.max(8,side/100)){const ab=a.clone().add(b).multiplyScalar(.5),bc=b.clone().add(c).multiplyScalar(.5),ca=c.clone().add(a).multiplyScalar(.5);tri(a,ab,ca,depth+1);tri(ab,b,bc,depth+1);tri(ca,bc,c,depth+1);tri(ab,bc,ca,depth+1);}else for(const q of [a,b,c])verts.push(...pos([q.x,q.y],.12));}for(const face of faces)tri(...face.map(i=>all[i]));if(verts.length){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(verts,3));geometry.computeVertexNormals();scene.add(new T.Mesh(geometry,mat(water?0x78acbe:play?0xc9b88f:road?0xb3ada1:0x83a77a)));counts.surfaces++;}}
}return counts;}


